:root {










  --main-background: #f6efe9;
  --main-foreground: #000000;

  --accent-color: #d27e29;

  --button-primary-background-color: #d27e29;
  --button-primary-foreground-color: #FFFFFF;

  --button-primary-border-radius: 4px;
      --button-primary-background: #d27e29;
    --button-primary-border: 1px solid #FFFFFF;
    --button-primary-color: #FFFFFF;
    --button-primary-fill: #FFFFFF;

  --button-secondary-border-radius: 4px;
      --button-secondary-background: #FFFFFF;
    --button-secondary-border: 1px solid #000000;
    --button-secondary-color: #000000;
    --button-secondary-fill: #000000;
    --button-secondary-text-decoration: none;

  --button-tertiary-border-radius: 40px;
      --button-tertiary-background: transparent;
    --button-tertiary-border: 0;
    --button-tertiary-color: #000000;
    --button-tertiary-fill: #000000;
    --button-tertiary-text-decoration: underline;

  --label-primary-background: #d27e29;
  --label-primary-foreground: #ffffff;
  --label-primary-border-radius: 4px;
      --label-primary-border: 0;

  --label-secondary-background: #d27e29;
  --label-secondary-foreground: #ffffff;
  --label-secondary-border-radius: 4px;
      --label-secondary-border: 0;



  --main-foreground-opacity-03: #00000008;
  --main-foreground-opacity-05: #0000000D;
  --main-foreground-opacity-10: #0000001A;
  --main-foreground-opacity-20: #00000033;
  --main-foreground-opacity-30: #0000004D;
  --main-foreground-opacity-40: #00000066;
  --main-foreground-opacity-50: #00000080;
  --main-foreground-opacity-60: #00000099;

  --main-background-opacity-30: #f6efe94D;
  --main-background-opacity-50: #f6efe980;
  --main-background-opacity-80: #f6efe9CC;

  --label-secondary-background-80: #d27e29CC;


  --success: #4bb98c;
  --danger: #dd7774;
  --warning: #dc8f38;

      --stock-color: #664D3A;



  --heading-font: "Poppins", sans-serif;
  --body-font: "Poppins", sans-serif;



  --font-base: 14px;
  --font-base-default: 16px;


  --font-huge: 24px;
  --font-big: 18px;
  --font-medium: 16px;
  --font-small: 14px;
  --font-smallest: 12px;
  --font-extra-smallest: 11px;



  --h1: 50px;
  --h2: 42px;
  --h3: 34px;
  --h4: 29px;
  --h5: 24px;
  --h6: 20px;
  --h6-small: 17px;



  --title-font-weight: 700;



  --spacing-base: 16px;
  --spacing-half: calc(var(--spacing-base) / 2);
  --spacing-quarter: calc(var(--spacing-base) / 4);

  --spacing-1: calc(var(--spacing-base) * 0.25);
  --spacing-2: calc(var(--spacing-base) * 0.5);
  --spacing-3: var(--spacing-base);
  --spacing-4: calc(var(--spacing-base) * 1.5);
  --spacing-5: calc(var(--spacing-base) * 3);

  --spacing-section: calc(var(--spacing-base) * 4);
  --spacing-section-small: calc(var(--spacing-base) * 2);


  --section-content-lateral-padding: calc(var(--spacing-base) * 5);


  --icon-size-md: 0.875em;
  --icon-size-lg: 1.33em;
  --icon-size-2x: 2em;


  --gutter: var(--spacing-base);
  --gutter-container: var(--gutter);
  --gutter-container-md: calc(var(--gutter) * 2);
  --gutter-negative: calc(var(--gutter) * -1);
  --gutter-half: calc(var(--gutter) / 2);
  --gutter-half-negative: calc(var(--gutter) * -1 / 2);
  --gutter-double: calc(var(--gutter) * 2);


    --page-width: 1160px;



  --transition-fast: all 0.2s ease;
  --transition-normal: all 0.3s ease;
  --transition-slow: all 1s ease;


  --drop-shadow: 0 0 8px 4px var(--main-foreground-opacity-05);


  --border-radius: 8px;
  --border-radius-medium: calc(var(--border-radius) / 1.3333);
  --border-radius-small: calc(var(--border-radius) / 2);
  --border-radius-smallest: calc(var(--border-radius) / 4);
  --border-radius-full: 100%;


  --border-solid: 1px solid;
}

