.draft-bar {
    position: fixed;
    top: 0;
    right: 0;
    width: 100%;
    height: 52px;
    background: #fff;
    border-bottom: 1px solid #d1d1d1;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 20px 12px 12px;
    font-family: 'Geist', 'CentraNube', Roboto, -apple-system, BlinkMacSystemFont, sans-serif;
    box-sizing: border-box;
    z-index: 999999;
    transition: all .35s cubic-bezier(.16,.68,.43,.99);
}

.draft-bar.is-collapsed {
    width: 48px;
    right: 12px;
    background: transparent;
    border-bottom: none;
    overflow: visible;
}

.draft-bar-content {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
}

.draft-bar.is-collapsed .draft-bar-content,
.draft-bar.is-collapsed .draft-bar-toggle--collapse {
    display: none;
}
.draft-bar:not(.is-collapsed) .draft-bar-toggle--expand {
    display: none;
}

.draft-bar-back {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
}

.draft-bar-back-icon {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background: #eef5ff;
    border-radius: 8px;
    flex-shrink: 0;
    cursor: pointer;
    text-decoration: none;
    transition: background .2s;
}
.draft-bar-back-icon:hover {
    background: #dceaff;
}
.draft-bar-back-icon svg {
    width: 16px;
    height: 16px;
    fill: #0059d5;
}
.draft-bar-back-icon .tooltip-text {
    visibility: hidden;
    opacity: 0;
    position: absolute;
    left: 100%;
    top: 50%;
    transform: translateY(-50%);
    margin-left: 8px;
    background: #333;
    color: #fff;
    font-size: 12px;
    line-height: 16px;
    padding: 4px 8px;
    border-radius: 6px;
    white-space: nowrap;
    pointer-events: none;
    transition: opacity .15s;
}
.draft-bar-back-icon:hover .tooltip-text {
    visibility: visible;
    opacity: 1;
}

.draft-bar-tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 13px;
    font-size: 12px;
    line-height: 16px;
    white-space: nowrap;
}
.draft-bar-tag-pip {
    width: 6px;
    height: 6px;
    border-radius: 50%;
}
.draft-bar-tag--draft {
    background: #fde4bc;
    color: #dc8e0f;
}
.draft-bar-tag--draft .draft-bar-tag-pip {
    background: #dc8e0f;
}

.draft-bar-description {
    flex: 1;
    font-size: 12px;
    line-height: 16px;
    color: #5d5d5d;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.draft-bar-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 8px;
    flex-shrink: 0;
    cursor: pointer;
    border: none;
    padding: 0;
    transition: opacity .2s;
}
.draft-bar-toggle:hover {
    opacity: 1;
}
.draft-bar-toggle svg {
    width: 16px;
    height: 16px;
}

.draft-bar-toggle--collapse {
    background: #eef5ff;
    transition: background .2s;
}
.draft-bar-toggle--collapse:hover {
    background: #d0e2ff;
}
.draft-bar-toggle--collapse svg {
    fill: #0059d5;
}

.draft-bar-toggle--expand {
    background: #0059d5;
}
.draft-bar-toggle--expand svg {
    fill: #fff;
}

@media (max-width: 767px) {
    .draft-bar-description {
        display: none;
    }
    .draft-bar-tag {
        font-size: 11px;
    }
}

