:root{--ds-surface:#f6efe9;--ds-raised:#fffaf5;--ds-line:#e8ddd0;--ds-ink:#2b2916;--ds-muted:#6f6656;--ds-olive:#565229;--ds-on-olive:#f6efe9;--ds-amber:#d27e29;--ds-amber-deep:#a65a14;--ds-amber-hover:#8f4d10;--ds-gold:#a65a14;--ds-r-sm:12px;--ds-r-md:20px;--ds-r-lg:28px;--ds-shadow-card:0 10px 30px -22px rgba(43,41,22,.45);--ds-shadow-cta:0 8px 18px -10px rgba(166,90,20,.65)}
body{color:var(--ds-ink)}
/*30.1 botao principal: um formato so*/
