:root body .btn-secondary,:root body a.btn.cml-pos-2,:root body a.cml-cp-b.alt{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding-left:26px;padding-right:26px;background-color:transparent!important;border:1.5px solid var(--ds-olive)!important;color:var(--ds-olive)!important;font-size:15px!important;font-weight:600!important;text-transform:none!important;letter-spacing:0!important;border-radius:999px!important;box-shadow:none!important}
