/*B design system v1*/
:root{--ds-surface:#f6efe9;--ds-raised:#fffaf5;--ds-line:#e8ddd0;--ds-ink:#2b2916;--ds-muted:#6f6656;--ds-olive:#565229;--ds-on-olive:#f6efe9;--ds-amber:#d27e29;--ds-amber-deep:#a65a14;--ds-amber-hover:#8f4d10;--ds-gold:#dfae58;--ds-r-sm:12px;--ds-r-md:20px;--ds-r-lg:28px;--ds-shadow-card:0 10px 30px -22px rgba(43,41,22,.45);--ds-shadow-cta:0 8px 18px -10px rgba(166,90,20,.65)}
body{color:var(--ds-ink)}
/*30.1 botao principal: um formato so*/
:root body .btn-primary,:root body a.btn-primary,:root body input.btn-primary,:root body a.cml-cp-b:not(.alt){display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding-left:26px;padding-right:26px;background-color:var(--ds-amber-deep)!important;border:1.5px solid var(--ds-amber-deep)!important;color:#fff!important;font-size:15px!important;font-weight:600!important;line-height:1.1!important;text-transform:none!important;letter-spacing:0!important;border-radius:999px!important;box-shadow:var(--ds-shadow-cta)}
:root body .btn-primary:hover,:root body a.cml-cp-b:not(.alt):hover{background-color:var(--ds-amber-hover)!important;border-color:var(--ds-amber-hover)!important}
input.btn-primary{display:inline-block}
/*30.2 botao secundario*/
:root body .btn-secondary,:root body a.btn.cml-pos-2,:root body a.cml-cp-b.alt{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding-left:26px;padding-right:26px;background-color:transparent!important;border:1.5px solid var(--ds-olive)!important;color:var(--ds-olive)!important;font-size:15px!important;font-weight:600!important;text-transform:none!important;letter-spacing:0!important;border-radius:999px!important;box-shadow:none!important}
:root body .btn-secondary:hover,:root body a.btn.cml-pos-2:hover,:root body a.cml-cp-b.alt:hover{background-color:var(--ds-olive)!important;color:var(--ds-on-olive)!important}
/*30.2b links Ver todos das vitrines: link, nao botao*/
:root body a.btn.cpvp-all{min-height:0;padding:6px 0!important;background:transparent!important;border:0!important;box-shadow:none!important;color:var(--ds-olive)!important;font-size:14px!important;font-weight:600!important;text-decoration:underline;text-underline-offset:4px;text-decoration-thickness:1px}
/*30.3 botao em faixa escura (Ver todos dos mais amados)*/
a.cml-b2-all{display:inline-flex;align-items:center;min-height:40px;padding:0 18px;border:1.5px solid var(--ds-on-olive)!important;color:var(--ds-on-olive)!important;font-size:14px!important;font-weight:600!important;border-radius:999px!important}
a.cml-b2-all:hover{background:var(--ds-on-olive)!important;color:var(--ds-olive)!important}
